<?php
declare(strict_types=1);

/**
 * More questions for the English Lab's thinnest topics (owner, 13 Nov 2026: "Fix the repetition issue").
 *
 * A topic's practice deals 6 to 8 questions, and from 13 Nov the Lab avoids what a member was asked in
 * their recent sessions (mlb_recent_seen). A topic with ten or twelve questions in its whole bank cannot
 * honour that past one session: 21 English topics had 13 or fewer, and "Practise again" on them handed
 * back most of the same questions. Each gets fourteen more here, two forms of seven, so every one of them
 * holds at least three fresh sessions.
 *
 * Appended AFTER every other module's forms in eng_forms(), so no existing form changes its number and
 * every stored session still replays. Rows follow englishlab-kit.php: [question, right answer, [[wrong,
 * why it is tempting] × 3], why the right one is right]. Our own sentences, set where a Nigerian learner
 * will recognise them; no question is taken from any examination's papers.
 */
function eng_more_forms(): array {
    return [
    'EN-029' => [
        eng_choose([
            ['“I asked for TEA, not coffee.” Which word carries the emphatic stress?', 'tea', [['asked', 'The contrast is not about asking.'], ['coffee', 'Coffee is the rejected item, said after the stressed word.'], ['I', 'Nobody else is being contrasted with the speaker.']], 'The contrast is tea versus coffee, so tea is stressed.'],
            ['To mean “not my brother’s phone”, which word in “That is MY phone” is stressed?', 'my', [['phone', 'That would contrast the phone with some other object.'], ['that', 'That would point at a different item.'], ['is', 'That would insist it really is, against a denial.']], 'The contrast is about whose phone, so the owner word is stressed.'],
            ['To mean “she did not walk, she ran”, which word in “Ngozi RAN to school” is stressed?', 'ran', [['Ngozi', 'That would answer who, not how.'], ['school', 'That would answer where.'], ['to', 'A small grammar word is stressed only in rare corrections.']], 'The new information is the manner of moving: ran.'],
            ['“We meet on TUESDAY.” What does stressing Tuesday suggest?', 'Someone thought it was another day.', [['Someone thought we would not meet.', 'That would stress meet.'], ['Someone thought others would meet.', 'That would stress we.'], ['Someone was shouting.', 'Emphatic stress is about meaning, not volume.']], 'Stress falls on the corrected detail: the day.'],
            ['To answer “Did Tunde break the window?” with “No, EMEKA broke it”, which word is stressed?', 'Emeka', [['broke', 'Breaking is not in doubt.'], ['it', 'The window is not in doubt.'], ['no', 'No is said, but the correction is the name.']], 'The correction is who did it, so the name is stressed.'],
            ['Which sentence stresses the right word to correct “You owe me five hundred naira”?', 'I owe you FOUR hundred naira.', [['I OWE you four hundred naira.', 'Owing is not in dispute.'], ['I owe YOU four hundred naira.', 'The person is not in dispute.'], ['I owe you four hundred NAIRA.', 'The currency is not in dispute.']], 'Only the amount is corrected, so the number is stressed.'],
            ['“She is coming TODAY.” Which question was the speaker most likely answering?', 'Is she coming tomorrow?', [['Is he coming today?', 'That would need SHE stressed.'], ['Is she leaving today?', 'That would need COMING stressed.'], ['Who is coming?', 'That would need SHE stressed.']], 'The stress corrects the day, so the doubt was about when.'],
        ], '{q}', 'Find the word that replaces what someone wrongly thought; that word takes the stress.', 'reasoning', 35),
        eng_choose([
            ['In normal, unemphatic speech, where does the main stress in “I bought a new bag” usually fall?', 'bag', [['I', 'Pronouns are usually unstressed.'], ['a', 'Articles are almost never stressed.'], ['bought', 'Verbs can be stressed, but the last content word usually takes the main stress.']], 'Without contrast, the main stress falls on the last content word.'],
            ['Which word is LEAST likely to carry stress in ordinary speech?', 'the', [['market', 'A noun is a content word.'], ['quickly', 'An adverb is a content word.'], ['Lagos', 'A name is a content word.']], 'Grammar words like the, a and of are normally unstressed.'],
            ['To show surprise at the price in “It costs TEN thousand?”, which word is stressed?', 'ten', [['costs', 'Costing is expected; the amount is the surprise.'], ['thousand', 'Thousand is part of the amount, but ten is the surprising figure.'], ['it', 'The item is not in question.']], 'The surprising detail is the number.'],
            ['“I DID lock the door.” What does stressing the helper verb did show?', 'The speaker insists, against a doubt.', [['The speaker is asking a question.', 'The sentence is a statement.'], ['The speaker means another door.', 'That would stress door.'], ['The speaker means someone else locked it.', 'That would stress I.']], 'Stressing do/did insists that the action really happened.'],
            ['To mean “the blue one, not the red one”, which word in “Pass me the BLUE pen” is stressed?', 'blue', [['pen', 'The object is the same.'], ['pass', 'The action is the same.'], ['me', 'The receiver is the same.']], 'The colour is the contrast.'],
            ['Which reply stresses the right word to “Is the meeting at three?” when it is at four?', 'No, it is at FOUR.', [['No, it IS at four.', 'Is is not the corrected detail.'], ['No, IT is at four.', 'It is the same meeting.'], ['No, it is AT four.', 'At is a grammar word.']], 'The corrected detail is the time.'],
            ['In “HE wrote the poem”, what is being made clear?', 'Who wrote it, against someone else.', [['What he wrote.', 'That would stress poem.'], ['That he wrote rather than read it.', 'That would stress wrote.'], ['Which poem.', 'That would stress the or poem.']], 'Stress on he picks him out from other people.'],
        ], '', 'Stress the word that carries the new or contrasting information.', 'concept', 30),
    ],
    'EN-030' => [
        eng_choose([
            ['A yes/no question such as “Are you coming?” usually ends with which tune?', 'A rising tune', [['A falling tune', 'Falling is usual for wh- questions and statements.'], ['A level tune', 'Level suggests the speaker has not finished.'], ['No tune', 'Every spoken sentence has a pitch pattern.']], 'Yes/no questions usually rise at the end.'],
            ['A wh- question such as “Where do you live?” usually ends with which tune?', 'A falling tune', [['A rising tune', 'Rising is usual for yes/no questions.'], ['A rise-fall on every word', 'Only the final stressed word carries the main tune.'], ['A level tune', 'Level suggests more is coming.']], 'Wh- questions usually fall at the end.'],
            ['A plain statement such as “I live in Ibadan.” usually ends with which tune?', 'A falling tune', [['A rising tune', 'A rise can turn it into a surprised question.'], ['A fall-rise', 'A fall-rise adds doubt or reservation.'], ['A level tune', 'Level suggests the list continues.']], 'Statements usually fall: the speaker is sure and finished.'],
            ['In a list “oranges, bananas and pawpaw”, the items before the last one usually take which tune?', 'Rising (more is coming)', [['Falling', 'A fall signals the list has ended.'], ['Rise-fall', 'That signals strong feeling, not a list.'], ['None', 'Each item carries a small tune.']], 'Each item rises until the last, which falls to close the list.'],
            ['A question tag that really asks, “You are new here, aren’t you?”, ends with which tune?', 'Rising', [['Falling', 'A falling tag expects agreement rather than asking.'], ['Level', 'Level sounds unfinished.'], ['Rise-fall', 'That signals surprise or strong feeling.']], 'A rising tag is a real question; a falling tag asks you to agree.'],
            ['A question tag that only asks for agreement, “Lovely day, isn’t it?”, ends with which tune?', 'Falling', [['Rising', 'Rising would make it a real question.'], ['Level', 'Level sounds unfinished.'], ['No tune', 'Every spoken tag has a tune.']], 'Falling tags invite agreement; the speaker is fairly sure.'],
            ['Said with a rise, “You’re leaving?” is heard as what?', 'A surprised question', [['A firm statement', 'A statement falls.'], ['An order', 'An order usually falls.'], ['A greeting', 'Greetings follow their own tunes.']], 'A rise on a statement turns it into a question, often surprised.'],
        ], '{q}', 'Rising asks or continues; falling states, finishes or expects agreement.', 'concept', 30),
        eng_choose([
            ['Which tune best fits a firm command, “Close the gate.”?', 'Falling', [['Rising', 'Rising would sound like a request for permission.'], ['Fall-rise', 'That adds doubt.'], ['Level', 'Level sounds unfinished.']], 'Commands normally fall.'],
            ['“Well… I might come” said with a fall-rise on might suggests what?', 'Doubt or a condition', [['Certainty', 'Certainty falls.'], ['Anger', 'Anger is shown by stress and volume as well.'], ['A list', 'Lists rise item by item.']], 'A fall-rise often adds reservation: maybe, but…'],
            ['Which tune does an exclamation such as “What a beautiful dress!” usually take?', 'Falling', [['Rising', 'Rising would make it a question.'], ['Level', 'Level sounds flat and unfinished.'], ['Fall-rise', 'That adds doubt to the praise.']], 'Exclamations usually fall, often from a high start.'],
            ['In “Would you like rice or yam?”, offered as a CHOICE between the two, how does the sentence end?', 'Rise on rice, fall on yam', [['Rise on yam', 'A final rise would ask yes or no to food in general.'], ['Fall on both', 'The first item rises before the choice is closed.'], ['Level throughout', 'A choice question has a clear pattern.']], 'A choice rises on the first option and falls on the last.'],
            ['Which word in a sentence normally carries the main pitch movement?', 'The last important (stressed) word', [['The first word', 'The first word rarely carries the main tune.'], ['Every word equally', 'Only the nucleus carries the main movement.'], ['The longest word', 'Length does not decide it.']], 'The main tune falls on the last stressed content word, the nucleus.'],
            ['Why does a reader’s voice rise on “first, second,” and fall on “and finally, third”?', 'The rises show the list continues; the fall closes it.', [['To show anger', 'Anger is not shown by this pattern.'], ['Because the words are long', 'Length does not decide the tune.'], ['To ask a question', 'A list is not a question.']], 'Rising signals more to come; falling signals the end.'],
            ['“Sorry?” said with a sharp rise most likely means what?', 'Please repeat that.', [['I apologise.', 'An apology usually falls.'], ['Goodbye.', 'Goodbye is not meant.'], ['I agree.', 'Agreement is not meant.']], 'A rising “Sorry?” asks the speaker to say it again.'],
        ], '', 'Listen for where the pitch goes on the last stressed word.', 'concept', 30),
    ],
    'EN-036' => [
        eng_choose([
            ['Which is the MAIN clause in “When the bell rang, the pupils lined up.”?', 'the pupils lined up', [['When the bell rang', 'When makes it subordinate; it cannot stand alone.'], ['the bell rang', 'It is inside the when clause.'], ['When the bell', 'Not a clause: no verb.']], 'The main clause can stand alone as a sentence.'],
            ['Which is the SUBORDINATE clause in “We stayed indoors because it was raining.”?', 'because it was raining', [['We stayed indoors', 'That stands alone: the main clause.'], ['it was raining', 'Leave out because and you lose what makes it subordinate.'], ['We stayed', 'Part of the main clause.']], 'The subordinate clause begins with its joining word, because.'],
            ['Which word turns “the market closes” into a subordinate clause?', 'before', [['and', 'And joins equal (main) clauses.'], ['but', 'But joins equal clauses.'], ['so', 'So joins equal clauses.']], 'Before the market closes cannot stand alone; it depends on a main clause.'],
            ['How many main clauses are in “Ada cooked and Bola washed the plates.”?', 'Two', [['One', 'Each has its own subject and verb and can stand alone.'], ['Three', 'There are only two subject-verb pairs.'], ['None', 'Both parts can stand alone.']], 'And joins two main clauses of equal rank.'],
            ['Which of these can stand alone as a sentence?', 'The shop was closed.', [['Although the shop was closed.', 'Although leaves it waiting for a main clause.'], ['If the shop was closed.', 'If makes it a condition, not a sentence.'], ['Because the shop was closed.', 'Because makes it a reason, waiting for its result.']], 'A main clause makes complete sense on its own.'],
            ['In “The boy who won the prize is my cousin”, which part is the subordinate clause?', 'who won the prize', [['The boy is my cousin', 'That is the main clause, split around the relative clause.'], ['my cousin', 'A phrase, not a clause.'], ['won the prize', 'Without who it is not the relative clause.']], 'A relative clause beginning with who describes the boy.'],
            ['Which sentence is a fragment (a subordinate clause standing alone)?', 'Since we moved to Kano.', [['We moved to Kano.', 'A complete sentence.'], ['We moved to Kano last year.', 'A complete sentence.'], ['Since then, we have lived in Kano.', 'Since then is a phrase; the clause is main.']], 'Since we moved… needs a main clause to complete it.'],
        ], '{q}', 'A main clause stands alone; a subordinate clause starts with a word like because, when, if, who or although.', 'reasoning', 35),
        eng_choose([
            ['What kind of subordinate clause is “if you study” in “You will pass if you study.”?', 'A condition (adverbial clause)', [['A relative clause', 'Relative clauses begin with who, which, that and describe a noun.'], ['A noun clause', 'It does not act as a noun.'], ['A main clause', 'If makes it subordinate.']], 'If introduces a condition: an adverbial clause.'],
            ['What does the clause “that she was late” do in “She said that she was late.”?', 'It is the object of said (a noun clause).', [['It describes she.', 'It does not describe a noun.'], ['It gives a time.', 'It gives what was said.'], ['It is the main clause.', 'That makes it subordinate.']], 'The clause answers “said what?”: a noun clause as object.'],
            ['Which joining word introduces a clause of reason?', 'because', [['although', 'Although introduces contrast.'], ['unless', 'Unless introduces a condition.'], ['until', 'Until introduces time.']], 'Because gives the reason for the main clause.'],
            ['Which joining word introduces a clause of contrast?', 'although', [['because', 'Because gives a reason.'], ['when', 'When gives time.'], ['so that', 'So that gives purpose.']], 'Although sets up a contrast with the main clause.'],
            ['In “I will wait until you return”, what does the subordinate clause tell us?', 'How long (time)', [['Why', 'No reason is given.'], ['Where', 'No place is given.'], ['Which person', 'It does not describe a noun.']], 'Until introduces a time clause.'],
            ['Which sentence has a relative clause?', 'The bus that we took was late.', [['The bus was late because of traffic.', 'Because gives a reason: adverbial.'], ['When the bus came, we boarded.', 'When gives time: adverbial.'], ['The bus was late and full.', 'No subordinate clause at all.']], 'That we took describes the bus: a relative clause.'],
            ['Join as main + subordinate: “It was hot.” “We opened the windows.”', 'Because it was hot, we opened the windows.', [['It was hot, we opened the windows.', 'A comma splice: two main clauses joined by a comma.'], ['It was hot and because we opened the windows.', 'Mixes two joiners and breaks the sense.'], ['Because it was hot.', 'A fragment: the main clause is missing.']], 'Because makes the reason subordinate to the main clause.'],
        ], '', 'Ask what job the clause does: condition, reason, time, contrast, describing a noun, or acting as a noun.', 'concept', 35),
    ],
    'EN-041' => [
        eng_choose([
            ['“Lagos traffic wastes hours each day. Workers leave home at dawn, pupils arrive late, and goods spoil in lorries stuck on bridges.” What is the main idea?', 'Lagos traffic costs people a great deal of time and loss.', [['Workers leave home at dawn.', 'One detail.'], ['Goods spoil in lorries.', 'One detail.'], ['Bridges are dangerous.', 'Not said at all.']], 'The main idea covers all the details: traffic wastes time and causes loss.'],
            ['“Groundnuts are eaten roasted, ground into paste, pressed for oil, and fed to animals as cake.” What is the main idea?', 'Groundnuts have many uses.', [['Groundnuts are roasted.', 'One use only.'], ['Groundnut oil is healthy.', 'Health is not mentioned.'], ['Animals eat groundnut cake.', 'One use only.']], 'Every detail is a use: the main idea is the many uses.'],
            ['Where is the main idea of a paragraph MOST often stated?', 'In the first sentence (the topic sentence)', [['In the middle sentence', 'The middle usually holds supporting details.'], ['In the title only', 'The paragraph itself usually states it.'], ['Nowhere', 'Most paragraphs state it, usually first.']], 'Writers usually open with the topic sentence.'],
            ['“The well was dug, the clinic was painted, and a new road reached the village.” Which title fits best?', 'Changes in the Village', [['The New Road', 'Too narrow: one detail.'], ['Painting the Clinic', 'Too narrow.'], ['Life in Nigeria', 'Too wide.']], 'A good title is wide enough for every detail and no wider.'],
            ['Which is a SUPPORTING detail rather than the main idea in a paragraph about why reading helps pupils?', 'Readers learn new words.', [['Reading helps pupils in many ways.', 'That is the main idea.'], ['Reading is good.', 'Too vague to support anything.'], ['Pupils should never read.', 'The opposite of the paragraph.']], 'A detail gives one example of the main idea.'],
            ['“Some birds migrate to escape cold; others move to find food; a few travel to breed in safer places.” What is the main idea?', 'Birds migrate for different reasons.', [['Birds escape the cold.', 'One reason only.'], ['Birds breed in safe places.', 'One reason only.'], ['All birds migrate.', 'The passage says some, others, a few.']], 'The main idea gathers the reasons.'],
            ['A passage describes a market’s noise in the morning, its crowds at noon and its emptiness at dusk. What is the main idea?', 'How the market changes through the day', [['The market is noisy.', 'True only in the morning.'], ['Markets are dangerous.', 'Not said.'], ['Sweepers work at dusk.', 'A detail.']], 'The idea that holds every detail is change through the day.'],
        ], '{q}', 'The main idea is wide enough to hold every detail, and no wider.', 'reasoning', 45),
        eng_choose([
            ['Which question helps you find the main idea of a paragraph?', 'What is the whole paragraph mostly about?', [['What is the longest word?', 'Length does not show the main idea.'], ['What happens in the last line?', 'The last line may be only a detail.'], ['Who is the author?', 'Not the paragraph’s point.']], 'Ask what the whole paragraph is mostly about.'],
            ['A main idea that is TOO NARROW…', 'covers only one detail.', [['covers every detail.', 'That is a good main idea.'], ['is always wrong grammar.', 'Grammar is not the issue.'], ['is the title.', 'A title can be narrow or wide.']], 'Too narrow means it leaves details out.'],
            ['A main idea that is TOO WIDE…', 'claims more than the paragraph says.', [['names one example.', 'That is too narrow.'], ['repeats the first sentence.', 'Repeating can be correct.'], ['has a verb.', 'Every sentence has a verb.']], 'Too wide means it goes beyond the paragraph.'],
            ['“Exercise strengthens the heart, lifts the mood and helps sleep.” Which is TOO WIDE as its main idea?', 'Everything about health', [['Exercise has several benefits.', 'That fits exactly.'], ['Exercise strengthens the heart.', 'That is too narrow.'], ['Exercise helps sleep.', 'That is too narrow.']], 'All of health is far more than the paragraph covers.'],
            ['Which sentence would be the topic sentence of a paragraph about saving money?', 'There are simple ways to save money every week.', [['I bought a bag yesterday.', 'An unrelated detail.'], ['Banks open at eight.', 'A detail, not the point.'], ['Money is paper.', 'Not about saving.']], 'A topic sentence states the paragraph’s point in general terms.'],
            ['Why is “the first sentence” not ALWAYS the main idea?', 'Some writers build up to it and state it last.', [['First sentences are never important.', 'They often are.'], ['The main idea is always the title.', 'Not always.'], ['Paragraphs have no main idea.', 'Most do.']], 'Check whether the paragraph leads up to its point.'],
            ['Which of these is the main idea, not a detail? (A paragraph on the harmattan)', 'The harmattan brings dry, dusty, cold weather.', [['Lips crack.', 'A detail.'], ['Dust settles on tables.', 'A detail.'], ['Mornings are cold.', 'A detail.']], 'The details all show the weather the harmattan brings.'],
        ], '', 'Test each choice: does it cover every detail, and nothing more?', 'reasoning', 40),
    ],
    'EN-046' => [
        eng_choose([
            ['“I have told you a million times!” What device is this?', 'Hyperbole', [['Euphemism', 'Nothing unpleasant is softened.'], ['Irony', 'The speaker means many times; there is no reversal.'], ['Simile', 'There is no like or as.']], 'A deliberate exaggeration for effect is hyperbole.'],
            ['“He passed away last night.” What device replaces “he died”?', 'Euphemism', [['Hyperbole', 'Nothing is exaggerated.'], ['Irony', 'The meaning is not reversed.'], ['Personification', 'Nothing human is given to an object.']], 'A gentle phrase for something painful is a euphemism.'],
            ['A fire station burns down. What kind of irony is this?', 'Situational irony', [['Verbal irony', 'Nobody is saying the opposite of what they mean.'], ['Hyperbole', 'Nothing is exaggerated.'], ['Euphemism', 'Nothing is softened.']], 'The opposite of what you would expect happens.'],
            ['Soaked in the rain, Musa says “Lovely weather!” What is this?', 'Verbal irony', [['Hyperbole', 'Lovely is not an exaggeration of wet; it is the reverse.'], ['Euphemism', 'He is not being polite about something unpleasant.'], ['A simile', 'There is no comparison.']], 'Saying the opposite of what you mean is verbal irony.'],
            ['“This bag weighs a ton!” Which device is used?', 'Hyperbole', [['Irony', 'The bag really is heavy; the meaning is not reversed.'], ['Euphemism', 'Nothing is softened.'], ['Metaphor', 'The bag is not called something else.']], 'A ton is an exaggeration of heavy.'],
            ['“He is between jobs.” What is this a euphemism for?', 'He has no job.', [['He has two jobs.', 'Between does not mean both.'], ['He is changing offices.', 'That is not what is softened.'], ['He is retired.', 'Retired is a different situation.']], 'Between jobs gently says unemployed.'],
            ['The audience knows the food is poisoned but the character does not. What is this called?', 'Dramatic irony', [['Situational irony', 'This is about what the audience knows that a character does not.'], ['Verbal irony', 'No one is saying the opposite of what they mean.'], ['Hyperbole', 'Nothing is exaggerated.']], 'Dramatic irony: the audience knows more than the character.'],
        ], '{q}', 'Exaggeration is hyperbole; softening is euphemism; a reversal of meaning or expectation is irony.', 'concept', 35),
        eng_choose([
            ['Which sentence uses hyperbole?', 'I could sleep for a year.', [['I slept for eight hours.', 'A plain fact.'], ['I sleep like a log.', 'A simile.'], ['My bed calls to me.', 'Personification.']], 'A year of sleep is a deliberate exaggeration.'],
            ['Which sentence uses a euphemism?', 'The company is letting some staff go.', [['The company sacked some staff.', 'The plain word, not softened.'], ['The company is a giant.', 'A metaphor.'], ['The company sacked a thousand million staff.', 'Hyperbole.']], 'Letting go softens sacking.'],
            ['Which is an example of verbal irony?', 'After failing, Tunde says, “Well, that went brilliantly.”', [['Tunde says, “I failed.”', 'A plain statement.'], ['Tunde says, “I failed a thousand times.”', 'Hyperbole.'], ['Tunde says, “I did not quite pass.”', 'Understatement softening the result.']], 'He means the opposite of brilliantly.'],
            ['Why might a writer use a euphemism?', 'To be polite or gentle about something unpleasant', [['To exaggerate', 'That is hyperbole.'], ['To confuse the reader on purpose', 'Not its aim.'], ['To make a comparison', 'That is a simile or metaphor.']], 'Euphemisms soften what is painful or rude.'],
            ['Why might a writer use hyperbole?', 'To emphasise a feeling strongly', [['To be exact', 'Hyperbole is deliberately not exact.'], ['To soften bad news', 'That is euphemism.'], ['To say the opposite', 'That is irony.']], 'Exaggeration stresses how strongly something is felt.'],
            ['A traffic warden gets a fine for parking badly. What is ironic?', 'The person who enforces the rule broke it.', [['Fines are expensive.', 'True, but not the irony.'], ['Parking is hard.', 'Not the irony.'], ['Wardens wear uniforms.', 'Not the irony.']], 'The irony is the gap between the role and the act.'],
            ['“Senior citizens” is a euphemism for which plainer words?', 'Old people', [['Leaders', 'Senior here is about age, not rank.'], ['Citizens of a city', 'The phrase is about age.'], ['Teachers', 'Not the meaning.']], 'Senior citizens gently says old people.'],
        ], '', 'Ask: is it exaggerated, softened, or the reverse of what is meant or expected?', 'concept', 35),
    ],
    'EN-047' => [
        eng_choose([
            ['“The wind howled, the shutters banged, and the lamp flickered out.” What MOOD does this create?', 'Fear and tension', [['Joy', 'Nothing cheerful is described.'], ['Calm', 'Howling and banging are not calm.'], ['Boredom', 'The details are dramatic.']], 'Mood is the feeling a passage creates in the reader.'],
            ['“Honestly, who still believes the bus will come on time?” What is the writer’s TONE?', 'Sarcastic', [['Admiring', 'There is no praise.'], ['Sad', 'The question mocks rather than mourns.'], ['Neutral', 'The question is loaded with attitude.']], 'Tone is the writer’s attitude; this one mocks.'],
            ['What is the difference between tone and mood?', 'Tone is the writer’s attitude; mood is the feeling created in the reader.', [['They mean exactly the same.', 'They are different.'], ['Tone is about sound only.', 'Tone in writing is attitude.'], ['Mood is the writer’s attitude.', 'That is tone.']], 'Tone belongs to the writer; mood to the reader’s experience.'],
            ['“Children laughed, drums beat, and the smell of jollof filled the compound.” What mood is created?', 'Festive and happy', [['Gloomy', 'Laughter and drums are not gloomy.'], ['Tense', 'Nothing threatens.'], ['Lonely', 'The scene is crowded and lively.']], 'The details point to celebration.'],
            ['Which word best describes the tone of “We must act now, before it is too late.”?', 'Urgent', [['Playful', 'Nothing light-hearted.'], ['Bored', 'Must and now show energy.'], ['Uncertain', 'Must shows certainty.']], 'Must, now and too late create urgency.'],
            ['“Sadly, the old school was pulled down, and with it went our childhood.” What is the tone?', 'Nostalgic and sad', [['Angry', 'There is loss but no anger.'], ['Humorous', 'Nothing is funny.'], ['Excited', 'The words point to loss.']], 'Sadly and childhood signal longing for the past.'],
            ['Which detail would make a scene feel PEACEFUL?', 'A slow river shining under the evening sun', [['Sirens wailing in the night', 'Alarming.'], ['A crowd pushing at a gate', 'Tense.'], ['Thunder cracking overhead', 'Threatening.']], 'Slow, soft, bright details build peace.'],
        ], '{q}', 'Tone: the writer’s attitude. Mood: the feeling the passage gives the reader. Look at the word choices.', 'reasoning', 40),
        eng_choose([
            ['Which word could describe a writer’s TONE?', 'critical', [['sunny', 'That describes weather, not attitude.'], ['tall', 'That describes size.'], ['blue', 'A colour.']], 'Tone words name attitudes: critical, admiring, sarcastic, serious.'],
            ['Which word best names the mood of a ghost story?', 'eerie', [['cheerful', 'Ghost stories are rarely cheerful.'], ['businesslike', 'That is a tone of reports.'], ['sleepy', 'Not the usual effect.']], 'Eerie: strange and frightening.'],
            ['A letter to a council about uncollected rubbish should take which tone?', 'Firm and polite', [['Rude and angry', 'Rudeness weakens the complaint.'], ['Jokey', 'The matter is serious.'], ['Pleading and tearful', 'A complaint states facts firmly.']], 'Formal complaints are firm but courteous.'],
            ['“What a wonderful idea — another meeting to plan the next meeting.” What is the tone?', 'Ironic', [['Sincere', 'The writer does not mean wonderful.'], ['Fearful', 'Nothing is feared.'], ['Grateful', 'There is no thanks.']], 'The praise is the opposite of what is meant.'],
            ['Which change makes “The room was dark” feel more frightening?', 'The room was dark, and something breathed in the corner.', [['The room was dark, so I slept well.', 'That feels calm.'], ['The room was dark and tidy.', 'Tidy calms it.'], ['The room was dark; I switched on the light.', 'The tension is relieved.']], 'An unknown presence creates fear.'],
            ['A headline says “Heroic nurses save hundreds”. What is its tone toward the nurses?', 'Admiring', [['Critical', 'Heroic praises them.'], ['Neutral', 'Heroic is not neutral.'], ['Mocking', 'Nothing mocks.']], 'Heroic shows admiration.'],
            ['Which words show a writer’s tone is NEUTRAL?', 'The meeting began at nine and ended at noon.', [['The dreadful meeting dragged on.', 'Dreadful shows attitude.'], ['The brilliant meeting flew by.', 'Brilliant shows attitude.'], ['Sadly, the meeting ran late.', 'Sadly shows attitude.']], 'Plain facts without feeling words are neutral.'],
        ], '', 'Find the feeling words: they reveal the tone and build the mood.', 'concept', 35),
    ],
    'EN-048' => [
        eng_choose([
            ['A summary question asks for “two reasons”. How many points should you give?', 'Exactly two', [['As many as possible', 'Extra points can be marked wrong or waste time.'], ['One long point', 'Two separate points are asked for.'], ['Two, plus examples', 'Examples are not points.']], 'Give exactly what is asked.'],
            ['Which belongs in a summary?', 'A key point in your own words', [['An example the writer gives', 'Examples illustrate; they are not points.'], ['Your opinion of the writer', 'A summary reports, it does not judge.'], ['A long quotation', 'Use your own words.']], 'A summary keeps the key points and leaves out examples and opinions.'],
            ['“Farmers now sell by phone. For instance, a woman in Benue calls three markets.” Which is the KEY POINT?', 'Farmers now sell their crops by phone.', [['A woman in Benue calls three markets.', 'That is the example.'], ['Benue is a state.', 'Background, not the point.'], ['Phones are cheap.', 'Not said.']], 'Leave out the example; keep the point it illustrates.'],
            ['Why should a summary avoid lifting whole sentences from the passage?', 'It must show you understood, in your own words.', [['Lifted sentences are always wrong grammar.', 'They may be correct but are not your words.'], ['Passages are copyrighted.', 'Not the reason in an exercise.'], ['Lifting is shorter.', 'It is usually longer.']], 'Own words prove understanding.'],
            ['Which is the best summary of “The borehole means girls no longer miss lessons fetching water, and the clinic sees less typhoid.”?', 'The borehole improved schooling and health.', [['Girls fetch water.', 'They no longer do.'], ['The clinic was built.', 'Not said.'], ['Typhoid exists.', 'A detail without the point.']], 'Two benefits, said briefly in your own words.'],
            ['What should you do FIRST when writing a summary?', 'Read the question to see exactly what is asked.', [['Start writing at once.', 'You must know what to look for.'], ['Count the words in the passage.', 'Not the first step.'], ['Copy the first paragraph.', 'Copying is not summarising.']], 'The question decides which points you need.'],
            ['Which word should NOT normally appear in a points summary?', 'etc.', [['because', 'It can give a reason.'], ['and', 'It can join ideas.'], ['therefore', 'It can show a result.']], '“Etc.” is vague; a summary names its points.'],
        ], '{q}', 'Find exactly what the question asks for; give those points only, in your own words.', 'reasoning', 45),
        eng_choose([
            ['A passage lists three dangers of the harmattan with an example of each. A summary of the dangers should contain…', 'the three dangers, without the examples', [['the three examples', 'Examples are not the dangers themselves.'], ['one danger in detail', 'All three are needed.'], ['the dangers and your advice', 'Advice is not in the passage.']], 'Keep the points; drop the illustrations.'],
            ['Which is a POINT, not an example? (A passage on why the library succeeded)', 'The librarian made reading social.', [['A Saturday club met.', 'How it was done: an example.'], ['Children borrowed two books.', 'A detail.'], ['Parents came to the first meeting.', 'A detail.']], 'The point is general; the examples show it.'],
            ['“Okada bans cut accidents but force commuters to walk far.” A one-sentence summary of the EFFECTS is…', 'The ban made roads safer but made travel harder.', [['Commuters walk.', 'Only one effect.'], ['Okada riders are angry.', 'Not in this sentence.'], ['The government made a ban.', 'The cause, not the effects.']], 'Both effects, briefly.'],
            ['Your summary is too long. What should you cut first?', 'Examples and repeated ideas', [['The key points', 'Those are what is asked for.'], ['The verbs', 'Sentences need verbs.'], ['Full stops', 'Punctuation is needed.']], 'Examples and repetition are the first to go.'],
            ['Which summary sentence is best?', 'Solar panels save fuel but weaken in the rainy season.', [['Solar panels are good, nice and useful, etc.', 'Vague and uses etc.'], ['Many households, many panels, many bulbs.', 'Not a sentence and no point.'], ['In my view solar is the future.', 'Your opinion is not in the passage.']], 'Clear points, one sentence, the writer’s ideas.'],
            ['What does “in your own words” mean in a summary?', 'Rewrite the idea using different words while keeping the meaning.', [['Write your opinion.', 'Not opinion: the writer’s ideas.'], ['Use only very short words.', 'Length is not the rule.'], ['Translate into another language.', 'Not translation.']], 'Same meaning, your wording.'],
            ['A summary of a story should mostly report…', 'the main events in order', [['every conversation', 'Too much detail.'], ['the reader’s feelings', 'Not the story.'], ['the title only', 'Too little.']], 'Main events, briefly, in order.'],
        ], '', 'A point is general; an example shows it. Summaries keep points.', 'reasoning', 45),
    ],
    'EN-051' => [
        eng_choose([
            ['Combine: “The rain stopped.” “We went out.”', 'When the rain stopped, we went out.', [['The rain stopped, we went out.', 'A comma alone cannot join two sentences.'], ['The rain stopped we went out.', 'A run-on: no joining word or punctuation.'], ['When the rain stopped.', 'A fragment: the main clause is gone.']], 'When joins the time clause to the main clause.'],
            ['Combine with a relative clause: “I met a girl.” “She speaks four languages.”', 'I met a girl who speaks four languages.', [['I met a girl which speaks four languages.', 'Which is for things, not people.'], ['I met a girl, she speaks four languages.', 'A comma splice.'], ['I met a girl who she speaks four languages.', 'Who already stands for she.']], 'Who replaces she and joins the clauses.'],
            ['Combine to show contrast: “He is rich.” “He is unhappy.”', 'Although he is rich, he is unhappy.', [['Because he is rich, he is unhappy.', 'Because gives a reason, not a contrast.'], ['He is rich so he is unhappy.', 'So gives a result, not a contrast.'], ['He is rich and unhappy because.', 'Because is left hanging.']], 'Although sets the two facts against each other.'],
            ['Combine to show result: “The road was flooded.” “The bus turned back.”', 'The road was flooded, so the bus turned back.', [['The road was flooded, although the bus turned back.', 'Although shows contrast.'], ['The road was flooded, because the bus turned back.', 'This reverses cause and effect.'], ['The road was flooded the bus turned back.', 'A run-on.']], 'So introduces the result.'],
            ['Combine with a participle: “Ada opened the letter.” “She smiled.”', 'Opening the letter, Ada smiled.', [['Opening the letter, the smile appeared.', 'A dangling participle: the smile did not open the letter.'], ['Ada opening the letter smiled she.', 'Broken word order.'], ['Opened the letter, Ada smiled.', 'Wrong form: opening, not opened.']], 'The participle phrase must belong to the subject that follows.'],
            ['Combine to show purpose: “She saved money.” “She wanted a laptop.”', 'She saved money so that she could buy a laptop.', [['She saved money although she wanted a laptop.', 'Although shows contrast.'], ['She saved money, she wanted a laptop.', 'A comma splice.'], ['She saved money because a laptop.', 'Because needs a clause, not a noun alone.']], 'So that introduces purpose.'],
            ['Which is the correctly combined sentence?', 'The market, which opens at six, is busy by seven.', [['The market which opens at six, is busy by seven.', 'The commas must come in a pair.'], ['The market, which opens at six is busy by seven.', 'The second comma is missing.'], ['The market is busy by seven, it opens at six.', 'A comma splice.']], 'A non-essential clause is enclosed by a pair of commas.'],
        ], '{q}', 'Pick the joining word that shows the relationship: time, reason, contrast, result or purpose.', 'procedure', 45),
        eng_choose([
            ['What is a comma splice?', 'Two sentences joined by only a comma', [['A sentence with too many commas', 'Not the definition.'], ['A sentence without a verb', 'That is a fragment.'], ['Two sentences joined by and', 'That is correct joining.']], 'A comma alone cannot join two main clauses.'],
            ['Which joining word shows an alternative?', 'or', [['but', 'But shows contrast.'], ['so', 'So shows result.'], ['because', 'Because shows reason.']], 'Or offers a choice.'],
            ['Combine without repeating the subject: “Musa washed the car.” “Musa polished the car.”', 'Musa washed and polished the car.', [['Musa washed the car and Musa polished the car.', 'Correct but repetitive.'], ['Musa washed, polished the car.', 'And is missing.'], ['Musa washed and polished.', 'The object is lost.']], 'Join the two verbs and keep one subject and one object.'],
            ['Which combined sentence avoids a fragment?', 'Because the exam was near, she studied every night.', [['Because the exam was near.', 'A fragment.'], ['Studied every night because the exam.', 'No subject, and the clause is incomplete.'], ['The exam was near. Because she studied.', 'The second part is a fragment.']], 'The because clause needs its main clause.'],
            ['Combine: “The film was long.” “The film was exciting.”', 'The film was long but exciting.', [['The film was long because exciting.', 'Because does not join adjectives this way.'], ['The film was long, exciting, but.', 'But is left hanging.'], ['The film was long so exciting.', 'So shows a result that does not follow.']], 'But links the two qualities and shows the contrast.'],
            ['Which sentence uses a semicolon correctly to combine two ideas?', 'The shop was shut; we went home.', [['The shop was shut; and we went home.', 'A semicolon replaces and; do not use both.'], ['The shop; was shut we went home.', 'The semicolon is in the wrong place.'], ['Because the shop was shut; we went home.', 'A semicolon cannot follow a subordinate clause.']], 'A semicolon joins two closely related main clauses.'],
            ['Which word combines two sentences to show that one thing happened first?', 'after', [['unless', 'Unless shows a condition.'], ['although', 'Although shows contrast.'], ['whereas', 'Whereas shows contrast.']], 'After orders the events in time.'],
        ], '', 'Joined sentences must make one clear sentence: no splices, no fragments, no repeated subjects.', 'procedure', 40),
    ],
    'EN-052' => [
        eng_choose([
            ['In a formal letter, where does the writer’s address go?', 'At the top right', [['At the bottom left', 'The bottom carries the signature.'], ['After the salutation', 'The salutation comes later.'], ['It is left out', 'A formal letter gives the writer’s address.']], 'The writer’s address starts the letter, at the top right.'],
            ['Which salutation suits a formal letter to a principal whose name you do not know?', 'Dear Sir/Madam,', [['Hi Principal,', 'Too casual.'], ['Dear Friend,', 'For informal letters.'], ['Hello there,', 'Too casual.']], 'Dear Sir/Madam is formal and safe when the name is unknown.'],
            ['Which closing goes with “Dear Sir/Madam”?', 'Yours faithfully,', [['Yours sincerely,', 'Used when you name the person.'], ['Your friend,', 'Informal.'], ['Love,', 'Far too informal.']], 'Unknown name: Yours faithfully.'],
            ['Which closing goes with “Dear Mrs Okafor”?', 'Yours sincerely,', [['Yours faithfully,', 'Used when the name is unknown.'], ['Cheers,', 'Too casual.'], ['Your loving pupil,', 'Too personal.']], 'Named person: Yours sincerely.'],
            ['What does a formal letter usually have just after the salutation?', 'A heading (title) stating the subject', [['A joke to relax the reader', 'Not formal.'], ['The writer’s signature', 'That comes at the end.'], ['A list of friends', 'Irrelevant.']], 'A heading tells the reader at once what the letter is about.'],
            ['Which opening sentence suits a formal letter?', 'I am writing to complain about the broken streetlights on our road.', [['How are you and your family?', 'That suits an informal letter.'], ['Guess what happened!', 'Too casual.'], ['I hope you remember me from the party.', 'Too personal.']], 'Formal letters state the purpose at once.'],
            ['Which word suits a formal letter?', 'request', [['wanna', 'Slang.'], ['stuff', 'Too vague and casual.'], ['gonna', 'Slang.']], 'Formal letters use standard, precise words.'],
        ], '{q}', 'Formal letters: two addresses, date, salutation, heading, purpose first, polite close.', 'concept', 35),
        eng_choose([
            ['Which is the best order for the body of a complaint letter?', 'State the problem, give details, say what you want done', [['Say what you want, then greet the reader', 'The greeting comes first and the request last.'], ['Give details, then introduce yourself at the end', 'Introductions belong at the start.'], ['Threaten first, explain later', 'Rude and unclear.']], 'Problem, evidence, request.'],
            ['Which sentence is too informal for a formal letter?', 'The food at the canteen is totally gross.', [['The food at the canteen is often cold.', 'Formal and specific.'], ['The canteen food has caused complaints.', 'Formal.'], ['I respectfully request that the menu be reviewed.', 'Formal.']], 'Totally gross is slang.'],
            ['Where does the RECEIVER’s address go in a formal letter?', 'On the left, below the writer’s address and date', [['At the top right', 'That is the writer’s address.'], ['After the closing', 'Too late.'], ['It is never written', 'Formal letters include it.']], 'Receiver’s address: left, before the salutation.'],
            ['What should follow “Yours faithfully,”?', 'Your signature and full name', [['Your nickname only', 'Too informal.'], ['A postscript joke', 'Not formal.'], ['The receiver’s name', 'Your own name signs it.']], 'Sign, then write your full name below.'],
            ['Which is the most polite request?', 'I would be grateful if you could repair the gate.', [['Repair the gate now.', 'A command.'], ['You must fix it or else.', 'A threat.'], ['Fix the gate, okay?', 'Too casual.']], 'I would be grateful if… is formal and polite.'],
            ['Which detail is LEAST suitable in a formal application letter?', 'Your favourite football club', [['Your qualifications', 'Relevant.'], ['Your experience', 'Relevant.'], ['When you can start', 'Relevant.']], 'Keep to what the reader needs.'],
            ['A formal letter should avoid contractions like “don’t”. Which is better?', 'do not', [['dont', 'Wrong spelling and still informal.'], ["don’t", 'A contraction.'], ['dun', 'Slang.']], 'Write words in full in formal letters.'],
        ], '', 'Polite, precise, purposeful: say why you write, give facts, ask clearly.', 'concept', 35),
    ],
    'EN-053' => [
        eng_choose([
            ['Which salutation suits an informal letter to a cousin?', 'Dear Chidi,', [['Dear Sir,', 'Formal.'], ['To whom it may concern,', 'Formal and impersonal.'], ['Dear Madam,', 'Formal.']], 'Informal letters use the person’s first name.'],
            ['Which closing suits an informal letter to a friend?', 'Your friend, Amaka', [['Yours faithfully, Amaka Obi', 'Formal.'], ['Yours sincerely, A. Obi', 'Formal.'], ['Regards, the management', 'Impersonal.']], 'A warm, personal close fits an informal letter.'],
            ['Does an informal letter need the receiver’s address?', 'No, only the writer’s address and date', [['Yes, always on the left', 'That is a formal letter feature.'], ['Yes, at the bottom', 'Not used.'], ['No address at all', 'The writer’s address is still given.']], 'Informal letters give the writer’s address and the date only.'],
            ['Which is a good opening paragraph for a letter to a friend?', 'How are you? I hope your new school is treating you well.', [['I am writing to complain about…', 'Formal.'], ['Dear Sir, kindly note…', 'Formal.'], ['Regarding your application…', 'Formal and impersonal.']], 'Informal letters open warmly and personally.'],
            ['Which word suits an informal letter but NOT a formal one?', 'Guess what!', [['I wish to inform you', 'Formal.'], ['Kindly', 'Formal.'], ['Furthermore', 'Formal linking word.']], 'Lively, chatty phrases suit informal letters.'],
            ['An informal letter may have a heading (title) after the salutation. True or false?', 'False: informal letters have no heading.', [['True: always.', 'Headings belong to formal letters.'], ['True, but only in pencil.', 'Not a rule.'], ['True: two headings.', 'Not a rule.']], 'No heading in an informal letter.'],
            ['What is the purpose of the last paragraph of a letter to a friend?', 'To end warmly, sending greetings and promising to write again', [['To state a complaint', 'Not a personal letter’s close.'], ['To list your address', 'The address is at the top.'], ['To introduce yourself', 'Your friend knows you.']], 'Close with greetings and good wishes.'],
        ], '{q}', 'Informal letters: writer’s address and date, first-name greeting, friendly tone, warm close.', 'concept', 35),
        eng_choose([
            ['Which sentence is too formal for a letter to your sister?', 'I wish to bring to your notice that I passed.', [['Guess what — I passed!', 'Friendly.'], ['You will be happy to hear I passed.', 'Friendly.'], ['I passed, can you believe it?', 'Friendly.']], 'Too stiff for a sister.'],
            ['Which detail suits the BODY of an informal letter?', 'News about your holiday and questions about theirs', [['A heading in capitals', 'Formal.'], ['The receiver’s address', 'Not used.'], ['A formal complaint', 'Not personal.']], 'Share news and ask about theirs.'],
            ['Where does the date go in an informal letter?', 'Below the writer’s address, top right', [['At the bottom', 'It goes at the top.'], ['After the salutation', 'It comes before.'], ['It is not needed', 'Letters are dated.']], 'Address, then date, top right.'],
            ['Which closing is WRONG for a letter to a friend?', 'Yours faithfully,', [['Your friend,', 'Fine.'], ['Best wishes,', 'Fine.'], ['With love,', 'Fine for close friends.']], 'Yours faithfully is for formal letters to unnamed people.'],
            ['Which best replies to a friend who wrote that she was ill?', 'I was sorry to hear you were ill; I hope you are better now.', [['Your illness is noted.', 'Cold and formal.'], ['Illness is common.', 'Unkind.'], ['Please find attached my report.', 'Formal.']], 'Show care, in a warm tone.'],
            ['Which is a suitable informal letter topic?', 'Telling your friend about your new school', [['Applying for a job', 'Formal.'], ['Complaining to the council', 'Formal.'], ['Requesting a bank loan', 'Formal.']], 'Personal news suits informal letters.'],
            ['How should paragraphs in an informal letter be organised?', 'One topic of news per paragraph', [['All news in one long paragraph', 'Hard to read.'], ['One sentence per page', 'Not sensible.'], ['No paragraphs at all', 'Paragraphs still help.']], 'Group your news by topic.'],
        ], '', 'Write as you would talk to the person, but in correct, organised English.', 'concept', 35),
    ],
    'EN-054' => [
        eng_choose([
            ['What is a topic sentence?', 'The sentence that states the main point of a paragraph', [['The last sentence of an essay', 'That may be a conclusion.'], ['Any sentence with a long word', 'Length does not matter.'], ['The title', 'A title is not a sentence in the paragraph.']], 'It tells the reader what the paragraph is about.'],
            ['Which is the best topic sentence for a paragraph about the benefits of trees?', 'Trees benefit a community in several ways.', [['Mango trees grow in Nigeria.', 'Too narrow.'], ['I climbed a tree once.', 'A personal detail.'], ['Trees are green.', 'Does not set up benefits.']], 'It announces the point every sentence will support.'],
            ['Which sentence does NOT belong in a paragraph about why sleep matters?', 'My uncle sells phones.', [['Sleep helps memory.', 'Supports the point.'], ['Tired pupils find it hard to focus.', 'Supports the point.'], ['Sleep restores energy.', 'Supports the point.']], 'Every sentence must support the topic.'],
            ['When should you start a new paragraph?', 'When you move to a new point', [['After every sentence', 'Too often.'], ['Only once per essay', 'Too rarely.'], ['When the line ends', 'Line ends are not paragraph breaks.']], 'One point per paragraph.'],
            ['What do supporting sentences do?', 'Explain or give examples of the topic sentence', [['Introduce a new topic', 'That needs a new paragraph.'], ['Repeat the title', 'Not their job.'], ['Contradict the topic sentence', 'They support it.']], 'They develop the main point.'],
            ['Which word makes a good link at the start of the second paragraph of an argument?', 'Furthermore,', [['Once upon a time,', 'A story opening.'], ['In conclusion,', 'Ends an essay.'], ['Dear Sir,', 'A letter greeting.']], 'Furthermore adds a further point.'],
            ['A paragraph has a topic sentence about saving water and then talks about football. What is wrong?', 'It loses unity: the sentences no longer support the topic.', [['It is too short.', 'Length is not the problem.'], ['It has no capitals.', 'Not the problem.'], ['It uses a link word.', 'Not the problem.']], 'Unity: every sentence supports the one topic.'],
        ], '{q}', 'One paragraph, one point: a topic sentence, then sentences that support it.', 'concept', 35),
        eng_choose([
            ['Which is the best order for a paragraph?', 'Topic sentence, explanation, example, link to the next point', [['Example, topic sentence, conclusion of the essay', 'Muddled.'], ['Link, example, nothing else', 'No main point.'], ['Conclusion, then topic sentence', 'Reversed.']], 'State, explain, show, link.'],
            ['Which sentence best ends a paragraph about exercise?', 'Clearly, regular exercise keeps the body and mind strong.', [['Football is a sport.', 'Off the point.'], ['In the next essay I will write about food.', 'Not a paragraph close.'], ['Exercise.', 'A fragment.']], 'A concluding sentence rounds off the point.'],
            ['Which topic sentence is too broad for one paragraph?', 'Everything about Nigeria’s history', [['Lagos became the capital in 1914.', 'A narrow, single point.'], ['The market opens at six.', 'Narrow.'], ['Our school has a new library.', 'Narrow.']], 'A paragraph handles one manageable point.'],
            ['What makes a paragraph coherent?', 'Sentences follow in a clear order with links between them', [['It is very long', 'Length is not coherence.'], ['It has many big words', 'Not coherence.'], ['Each sentence is on a different topic', 'That breaks coherence.']], 'Coherence: logical order and clear links.'],
            ['Which supporting sentence is an EXAMPLE?', 'For instance, our class saved ₦5,000 by switching off fans.', [['Saving energy matters.', 'A point, not an example.'], ['Energy is power.', 'A definition.'], ['In conclusion, save energy.', 'A conclusion.']], 'For instance signals an example.'],
            ['Why indent or leave a space before a new paragraph?', 'To show the reader a new point begins', [['To fill the page', 'Not the reason.'], ['Because the teacher likes it', 'There is a real reason.'], ['To hide mistakes', 'No.']], 'Layout signals structure.'],
            ['Which sentence would best introduce a paragraph about the dangers of bush burning?', 'Bush burning causes serious harm to land and people.', [['Fire is hot.', 'Too vague.'], ['My friend saw smoke.', 'A detail.'], ['Rain falls in July.', 'Off the point.']], 'It states the paragraph’s point clearly.'],
        ], '', 'Check unity (one point) and coherence (clear order and links).', 'concept', 35),
    ],
    'EN-058' => [
        eng_choose([
            ['Where does the semicolon belong? “It was late we went home.”', 'It was late; we went home.', [['It was; late we went home.', 'It splits a clause.'], ['It was late we; went home.', 'Wrong place.'], ['It; was late we went home.', 'Wrong place.']], 'A semicolon joins two related main clauses.'],
            ['Which sentence uses a colon correctly?', 'Bring three things: a pen, a ruler and a calculator.', [['Bring: three things a pen, a ruler and a calculator.', 'The colon must come after the complete clause.'], ['Bring three: things a pen.', 'Wrong place.'], ['Bring three things a pen: a ruler and a calculator.', 'Wrong place.']], 'A colon introduces a list after a complete clause.'],
            ['Which sentence uses dashes correctly to add an aside?', 'My brother — the one in Abuja — is visiting.', [['My brother the one — in Abuja is visiting.', 'The dashes must enclose the aside.'], ['My — brother the one in Abuja is visiting.', 'Wrong place.'], ['My brother the one in Abuja — is — visiting.', 'Wrong place.']], 'A pair of dashes encloses extra information.'],
            ['When can a semicolon separate items in a list?', 'When the items already contain commas', [['Never', 'It can, for complex lists.'], ['Always instead of commas', 'Only for complex lists.'], ['Only after the last item', 'Not a rule.']], 'Lagos, Nigeria; Accra, Ghana; Lomé, Togo.'],
            ['Which sentence uses a colon to explain?', 'She had one wish: to see her mother again.', [['She had: one wish to see her mother again.', 'The colon breaks the clause.'], ['She: had one wish.', 'Wrong place.'], ['She had one wish to: see her mother again.', 'Wrong place.']], 'The colon introduces what the wish was.'],
            ['Which is WRONG?', 'Because it rained; we stayed in.', [['It rained; we stayed in.', 'Correct.'], ['It rained, so we stayed in.', 'Correct.'], ['We stayed in: it was raining.', 'Correct (the colon explains).']], 'A semicolon cannot follow a subordinate clause.'],
            ['What does a single dash at the end of a sentence often do?', 'Adds a dramatic final remark', [['Ends a question', 'A question mark does that.'], ['Starts a list', 'A colon does that.'], ['Joins two equal clauses formally', 'A semicolon does that.']], 'He opened the box and found nothing — nothing at all.'],
        ], '{q}', 'Semicolon: joins two main clauses. Colon: introduces a list or explanation. Dashes: set off an aside.', 'concept', 35),
        eng_choose([
            ['Which mark should replace the comma? “I love maths, it makes me think.”', 'A semicolon', [['A colon before a list', 'There is no list.'], ['A question mark', 'Not a question.'], ['Nothing; the comma is correct', 'It is a comma splice.']], 'Two main clauses need a semicolon (or a full stop).'],
            ['What must come BEFORE a colon?', 'A complete clause', [['A preposition', 'Never end on a preposition before a colon.'], ['A verb with no object', 'Leaves the clause incomplete.'], ['Nothing', 'Something complete must come first.']], 'The words before a colon must make sense alone.'],
            ['Which uses a colon correctly before a quotation?', 'The sign said only one thing: “Keep out.”', [['The sign: said only one thing “Keep out.”', 'Wrong place.'], ['The sign said: only one thing “Keep out.”', 'Wrong place.'], ['The sign said only one: thing “Keep out.”', 'Wrong place.']], 'The colon follows the complete clause and introduces the words.'],
            ['Which pair of sentences shows that a semicolon can replace “and”?', 'He studied hard; he passed. / He studied hard and he passed.', [['He studied; hard he passed.', 'Wrong place.'], ['He studied hard: and he passed.', 'Colon plus and is wrong.'], ['He; studied hard and passed.', 'Wrong place.']], 'A semicolon can do the joining work of and.'],
            ['Which punctuation suits “Three subjects worried her ___ maths, physics and chemistry.”?', 'a colon', [['a semicolon', 'A semicolon does not introduce a list.'], ['a question mark', 'Not a question.'], ['a full stop', 'The list would be a fragment.']], 'A colon introduces the list.'],
            ['Brackets and a pair of dashes can both…', 'add extra information to a sentence', [['end a question', 'Question marks do that.'], ['introduce a list', 'Colons do that.'], ['join two main clauses formally', 'Semicolons do that.']], 'Both enclose an aside; dashes are more emphatic.'],
            ['Which is punctuated correctly?', 'The results were clear: everyone passed.', [['The results; were clear everyone passed.', 'Wrong place.'], ['The results were: clear everyone passed.', 'Wrong place.'], ['The results were clear, everyone passed.', 'Comma splice.']], 'The colon introduces the explanation.'],
        ], '', 'Ask what the mark must do: join, introduce, or enclose.', 'procedure', 35),
    ],
    'EN-059' => [
        eng_choose([
            ['You are writing a speech to welcome parents to a prize-giving. Which opening fits?', 'Good afternoon, distinguished parents, teachers and fellow students.', [['Hey everyone, what’s up?', 'Too casual for the occasion.'], ['Dear Sir/Madam,', 'A letter opening, not a speech.'], ['Once upon a time…', 'A story opening.']], 'Speeches greet the audience by rank and role.'],
            ['Which is the right format for a notice of a club meeting?', 'A short heading, the date, time, place and who should attend', [['A long story about the club', 'Notices are brief.'], ['A formal letter with two addresses', 'Wrong format.'], ['A poem', 'Wrong format.']], 'Notices give the essentials at a glance.'],
            ['Writing a report for the principal on a school trip, which tone fits?', 'Factual and formal', [['Chatty and full of jokes', 'Reports are factual.'], ['Angry', 'Not appropriate.'], ['Poetic', 'Reports are plain.']], 'Reports present facts clearly and formally.'],
            ['Which belongs in an article for the school magazine?', 'A catchy title and a lively but correct style', [['Yours faithfully at the end', 'That ends a formal letter.'], ['The receiver’s address', 'Not used.'], ['No title', 'Articles need a title.']], 'Articles need a title and engage the reader.'],
            ['Writing a speech, how should you end it?', 'Thank the audience', [['Sign your name', 'Speeches are spoken.'], ['Write “Yours sincerely”', 'A letter ending.'], ['Stop mid-sentence', 'Incomplete.']], 'Speeches close by thanking the audience.'],
            ['Which suits a text message to a friend but NOT an essay?', 'C u at 4', [['I will see you at four o’clock.', 'Fine in both.'], ['Furthermore, the results show…', 'Essay style.'], ['In conclusion,', 'Essay style.']], 'Text-speak never belongs in formal writing.'],
            ['Writing for younger pupils, you should…', 'use short sentences and simple words', [['use as many long words as possible', 'They may not understand.'], ['write in slang', 'Not correct English.'], ['avoid examples', 'Examples help.']], 'Match the language to the reader.'],
        ], '{q}', 'Ask: who is reading or listening, and why? Then choose format, tone and words to fit.', 'reasoning', 40),
        eng_choose([
            ['Which three things decide how you write for an occasion?', 'Audience, purpose and format', [['Length, ink and paper', 'Not the deciding things.'], ['Weather, time and place', 'Not what decides style.'], ['Spelling, grammar and handwriting', 'Always needed, but they do not decide style.']], 'Know your reader, your aim and the form expected.'],
            ['Which is the best title for a report?', 'Report on the Inter-House Sports, 12 March', [['Wow! What a Day!', 'Better for an article.'], ['Dear Principal', 'A salutation.'], ['Yours faithfully', 'A closing.']], 'Report titles are plain and precise.'],
            ['A debate speech should mainly…', 'argue one side with reasons and evidence', [['tell a story with no point', 'A debate must argue.'], ['agree with both sides equally', 'Debaters take a side.'], ['list jokes', 'Not persuasive.']], 'Debates argue for or against a motion.'],
            ['Which sentence suits a formal speech?', 'I am honoured to stand before you today.', [['I am, like, so happy to be here.', 'Too casual.'], ['Yo, listen up.', 'Slang.'], ['Whatever, let us begin.', 'Rude and casual.']], 'Formal occasions need formal language.'],
            ['A diary entry is usually written…', 'in the first person, about your own day', [['as a formal letter', 'Wrong form.'], ['in the third person about a stranger', 'Diaries are personal.'], ['as a list of rules', 'Not a diary.']], 'Diaries are personal and first-person.'],
            ['Which detail belongs in a notice of a lost item?', 'A description of the item and how to return it', [['Your favourite food', 'Irrelevant.'], ['A long apology', 'Notices are brief.'], ['A greeting to the principal', 'Not needed.']], 'Give what helps someone act.'],
            ['Writing a speech, why address the audience directly (“you”)?', 'It involves the listeners and holds attention', [['It makes the speech shorter', 'Not the reason.'], ['It is required by grammar', 'Not a grammar rule.'], ['It avoids using names', 'Not the reason.']], 'Direct address engages listeners.'],
        ], '', 'Match the form to the occasion: speech, report, article, notice, letter or diary.', 'concept', 35),
    ],
    'EN-060' => [
        eng_choose([
            ['Which is the strongest reason for “Schools should have libraries”?', 'Libraries let every pupil read books their families cannot afford.', [['Libraries are buildings.', 'A fact, not a reason.'], ['I like libraries.', 'Opinion without support.'], ['Some schools have libraries.', 'Not a reason they should.']], 'A strong reason links clearly to the claim and benefits people.'],
            ['What is a counter-argument?', 'A point the other side would make', [['Your strongest point', 'That is your argument.'], ['The conclusion', 'Not the same.'], ['A spelling error', 'No.']], 'Good arguments answer the other side’s points.'],
            ['Which sentence REBUTS a counter-argument?', 'Some say uniforms are costly, but they save parents from buying many outfits.', [['Uniforms are blue.', 'No argument.'], ['Some say uniforms are costly.', 'States the counter-point without answering it.'], ['I hate uniforms.', 'Opinion only.']], 'State the objection, then answer it.'],
            ['Which is EVIDENCE rather than opinion?', 'Last year, 90% of pupils who used the library passed English.', [['The library is the best room.', 'Opinion.'], ['Everyone loves reading.', 'Overstated opinion.'], ['Books are fun.', 'Opinion.']], 'Evidence can be checked.'],
            ['Which is the best order for an argumentative essay?', 'State your position, give reasons with evidence, answer objections, conclude', [['Conclude first, then decide your position', 'Backwards.'], ['List evidence without a position', 'No claim to support.'], ['Answer objections only', 'Your own case is missing.']], 'Position, support, rebuttal, conclusion.'],
            ['Which is a weak argument?', 'Everybody knows it is true.', [['Studies show…', 'Evidence.'], ['For example, in our school…', 'An example.'], ['This saves money because…', 'A reason.']], 'Appeal to “everybody” proves nothing.'],
            ['Which linking word introduces a rebuttal?', 'However,', [['Firstly,', 'Begins a point.'], ['In addition,', 'Adds a point.'], ['For example,', 'Introduces an example.']], 'However turns from the objection to your answer.'],
        ], '{q}', 'A claim needs reasons, evidence and an answer to the other side.', 'reasoning', 45),
        eng_choose([
            ['Which sentence states a clear position?', 'Mobile phones should be allowed in school for learning.', [['Phones are a topic.', 'No position.'], ['Some people have phones.', 'A fact.'], ['Maybe phones, maybe not.', 'Undecided.']], 'A position says what you argue.'],
            ['Why give evidence in an argument?', 'To show your reasons are true', [['To make the essay longer', 'Not the purpose.'], ['To confuse the reader', 'No.'], ['Because the rules ask for numbers', 'Evidence can be examples too.']], 'Evidence supports reasons.'],
            ['Which conclusion is strongest?', 'For these reasons, every school should open a library this year.', [['That is all I have to say.', 'Weak and flat.'], ['Libraries, libraries, libraries.', 'No sense.'], ['I may be wrong about everything.', 'Undermines the case.']], 'Restate the position with a call to act.'],
            ['Which is an example used as support?', 'In Kano, a school library raised reading scores within a year.', [['Libraries are nice.', 'Opinion.'], ['Reading.', 'A fragment.'], ['Some say libraries cost money.', 'A counter-argument.']], 'A specific case supports the claim.'],
            ['What is wrong with attacking the person instead of the argument?', 'It ignores the reasons and proves nothing.', [['It makes the essay too formal.', 'Not the problem.'], ['It is always correct.', 'It is a fallacy.'], ['It is the best rebuttal.', 'It is not a rebuttal.']], 'Answer ideas, not people.'],
            ['Which word signals a RESULT in an argument?', 'Therefore,', [['However,', 'Contrast.'], ['For instance,', 'Example.'], ['Although,', 'Contrast.']], 'Therefore draws a conclusion from reasons.'],
            ['How many main reasons does a short argumentative essay usually need?', 'Two or three, each in its own paragraph', [['One sentence of reasons', 'Too thin.'], ['Twenty, all in one paragraph', 'Too many and unorganised.'], ['None if the title is clear', 'Reasons are essential.']], 'A few strong, developed reasons persuade best.'],
        ], '', 'Position, reasons, evidence, rebuttal, conclusion.', 'reasoning', 40),
    ],
    'EN-073' => [
        eng_choose([
            ['“The trader was frugal.” Which answer explains frugal IN YOUR OWN WORDS?', 'She was careful not to waste money.', [['She was frugal.', 'Repeats the word.'], ['She was a trader.', 'Does not explain the word.'], ['She sold many things.', 'Not the meaning.']], 'Own words: say the meaning without the word itself.'],
            ['“The pupils were jubilant after the match.” Which is the best own-words answer to “How did the pupils feel?”', 'They were extremely happy.', [['They were jubilant.', 'Lifts the passage’s word.'], ['They played a match.', 'Does not answer how they felt.'], ['They were tired.', 'Not what the text says.']], 'Replace the key word with your own.'],
            ['Why do examiners ask for answers “in your own words”?', 'To check that you understood, not just copied', [['To test handwriting', 'Not the aim.'], ['To make answers longer', 'Length is not the aim.'], ['To trick you', 'It tests understanding.']], 'Copying shows finding; own words show understanding.'],
            ['“The roads were impassable after the storm.” Which answer is in your own words?', 'No one could travel on the roads.', [['The roads were impassable.', 'Lifted.'], ['There was a storm.', 'Misses the point about the roads.'], ['The roads were wide.', 'Not the meaning.']], 'Impassable means it could not be travelled on.'],
            ['Which is the best own-words version of “He was reluctant to leave”?', 'He did not want to go.', [['He was reluctant to go.', 'Keeps the key word.'], ['He left quickly.', 'The opposite.'], ['He was leaving.', 'Loses the feeling.']], 'Reluctant: unwilling.'],
            ['A question asks: “What TWO things did the farmer do?” Your answer should…', 'name both things in a complete sentence', [['name one thing in detail', 'Two are asked for.'], ['copy the whole paragraph', 'Not an answer.'], ['give your opinion of the farmer', 'Not asked.']], 'Answer exactly what is asked, completely.'],
            ['“The village was desolate.” Which own-words answer fits?', 'It was empty and lonely.', [['It was desolate.', 'Lifted.'], ['It was crowded.', 'The opposite.'], ['It was a village.', 'No meaning given.']], 'Desolate: empty, lifeless, lonely.'],
        ], '{q}', 'Keep the meaning, change the words: never reuse the key word you are explaining.', 'reasoning', 45),
        eng_choose([
            ['Which answer to “Why did Uche start reading?” uses your own words?', 'His uncle gave him an exciting book that got him interested.', [['Uche did not like books until his uncle gave him a novel.', 'Copied.'], ['Because books.', 'A fragment.'], ['He likes motor parks.', 'Not the reason.']], 'Explain the reason freshly.'],
            ['What should you do if a word in the passage is hard to replace?', 'Explain its meaning in a short phrase.', [['Copy it anyway.', 'Not in your own words.'], ['Leave the answer blank.', 'You lose the mark.'], ['Invent a new word.', 'Not English.']], 'A short phrase can carry the meaning.'],
            ['“The speech was verbose.” Which answer is correct and in your own words?', 'It used far more words than necessary.', [['It was verbose.', 'Lifted.'], ['It was short and sharp.', 'The opposite.'], ['It was loud.', 'Not the meaning.']], 'Verbose: wordy.'],
            ['Which answer correctly explains “the meeting was postponed”?', 'The meeting was moved to a later date.', [['The meeting was postponed.', 'Lifted.'], ['The meeting was cancelled for ever.', 'Postponed is not cancelled.'], ['The meeting was held early.', 'The opposite.']], 'Postponed: put off till later.'],
            ['Answer “How did the market change by noon?” in your own words.', 'There were fewer people.', [['By noon the crowd thins.', 'Copied.'], ['It got louder.', 'Not what happens.'], ['It closed.', 'Not said.']], 'The crowd thins: fewer people.'],
            ['Which is the best way to answer a comprehension question?', 'In a full sentence that answers exactly what was asked', [['In one word, always', 'Often not enough.'], ['By copying the paragraph', 'Lifting.'], ['With your opinion', 'Not what is asked.']], 'Full, focused sentences.'],
            ['“She was apprehensive before the interview.” Which own-words answer is right?', 'She was worried about what would happen.', [['She was apprehensive.', 'Lifted.'], ['She was excited and calm.', 'Not the meaning.'], ['She was late.', 'Not the meaning.']], 'Apprehensive: anxious about the future.'],
        ], '', 'Show you understood by saying it differently, completely and to the point.', 'reasoning', 45),
    ],
    'EN-074' => [
        eng_choose([
            ['“The new clinic opened in June. It treats malaria, delivers babies and gives vaccines.” In ONE sentence, what services does the clinic offer?', 'The clinic treats malaria, delivers babies and gives vaccines.', [['The clinic opened in June.', 'A date, not the services.'], ['Malaria is dangerous.', 'Not in the passage.'], ['The clinic is new.', 'Not the services.']], 'Answer only what is asked, in one sentence.'],
            ['Which is a properly written summary point?', 'The scheme gave farmers better seeds.', [['better seeds', 'A phrase, not a sentence.'], ['The scheme, farmers, seeds, etc.', 'A list with etc.'], ['I think the scheme was great.', 'Your opinion.']], 'A full sentence stating one point.'],
            ['A question asks for ONE problem with the plan. Your answer gives three. What is wrong?', 'It gives more than was asked.', [['Nothing: more is better.', 'Extra points can cost marks.'], ['It is too short.', 'It is too long.'], ['It has no verb.', 'Not the issue.']], 'One point means one point.'],
            ['“Students who sleep well concentrate better, remember more and fall ill less.” In ONE sentence, why should students sleep well?', 'Good sleep helps students focus, remember and stay healthy.', [['Students sleep.', 'No reason given.'], ['They remember more.', 'Only part of the reason.'], ['Sleep is at night.', 'Irrelevant.']], 'One sentence can gather the benefits.'],
            ['Which summary sentence avoids adding your own judgement?', 'The council repaired the bridge.', [['The council finally did something useful by repairing the bridge.', 'Adds judgement.'], ['The lazy council repaired the bridge late.', 'Adds judgement.'], ['The bridge was, in my view, badly repaired.', 'Adds opinion.']], 'Report the point, not your view.'],
            ['How should you write the points of a summary?', 'Each point as a separate, complete sentence', [['All points in one long sentence with commas', 'Hard to mark and to read.'], ['As single words', 'Not sentences.'], ['As questions', 'Not statements.']], 'One point, one sentence.'],
            ['“The new bus route cut travel time, reduced fares and served three new estates.” In ONE sentence, give one benefit of the route.', 'The new route made journeys shorter.', [['The route is new.', 'Not a benefit.'], ['Buses are yellow.', 'Not in the passage.'], ['The route cut travel time, reduced fares and served three estates.', 'That gives three, not one.']], 'One benefit, one sentence, in your own words.'],
            ['“Before the borehole, girls walked two hours for water and often missed school.” In ONE sentence, what problem did the borehole solve?', 'Girls no longer had to walk far for water, so they could attend school.', [['There was a borehole.', 'Not the problem it solved.'], ['Water is wet.', 'Irrelevant.'], ['I think boreholes are good.', 'Your opinion.']], 'Name the problem and its effect in one sentence.'],
            ['“Plastic bags block drains, kill animals and take centuries to rot.” In ONE sentence, give one harm of plastic bags.', 'Plastic bags block drains.', [['Plastic bags are cheap.', 'Not a harm, and not in the passage.'], ['Drains are underground.', 'Not a harm.'], ['Plastic bags block drains, kill animals and take centuries to rot.', 'That gives three, not one.']], 'One point, as asked.'],
        ], '{q}', 'Answer exactly what is asked: the right number of points, each a complete sentence, no opinions.', 'reasoning', 50),
        eng_choose([
            ['Which word in a summary instruction tells you how many points to give?', 'The number (for example, “three”)', [['The title', 'The title does not say how many.'], ['The first word of the passage', 'Not relevant.'], ['The longest word', 'Not relevant.']], 'Underline the number in the question.'],
            ['Which is the best summary point from “Many youths leave villages for cities, seeking jobs that farming no longer provides”?', 'Young people move to cities to find work.', [['Many youths leave villages.', 'Leaves out why.'], ['Farming.', 'A word, not a point.'], ['Cities are big.', 'Not said.']], 'Who, what and why in one sentence.'],
            ['Your summary point contains “for example”. What should you do?', 'Remove the example and keep the point.', [['Add two more examples.', 'Examples are not points.'], ['Make it a question.', 'Not a summary.'], ['Leave it; examples are required.', 'They are not.']], 'Summaries leave examples out.'],
            ['“The library extended its hours, bought new books and started a reading club.” In ONE sentence, what did the library do to attract readers?', 'It opened longer, added books and began a reading club.', [['It is a library.', 'No point.'], ['It bought books.', 'Only part.'], ['Readers came.', 'The result, not what it did.']], 'All three actions, one sentence, own words.'],
            ['Which summary sentence repeats a point already made?', 'Also, the bridge was mended (after saying the bridge was repaired).', [['The road was widened.', 'A new point.'], ['A clinic was built.', 'A new point.'], ['Streetlights were fixed.', 'A new point.']], 'Each sentence should add a new point.'],
            ['Why keep summary sentences short?', 'To state each point clearly without extra detail', [['Because long words are banned', 'Not a rule.'], ['To use fewer full stops', 'Not the aim.'], ['To avoid verbs', 'Sentences need verbs.']], 'Short and clear: one point each.'],
            ['Which is NOT a summary point but background?', 'The town is in the north.', [['The market moved to a bigger site.', 'A point (what happened).'], ['Traders now have shelter from rain.', 'A point (a result).'], ['Prices fell after the move.', 'A point (a result).']], 'Background sets the scene; points answer the question.'],
        ], '', 'Count the points asked; write each once, as a complete sentence, without examples or opinion.', 'reasoning', 45),
    ],
    'EN-076' => [
        eng_choose([
            ['Which word begins with a consonant cluster?', 'string', [['sing', 'Begins with one consonant sound.'], ['apple', 'Begins with a vowel.'], ['hat', 'One consonant sound.']], 'str: three consonant sounds together.'],
            ['How many consonant sounds are in the cluster at the start of “splash”?', 'Three: s, p, l', [['Two', 'Count s, p and l.'], ['One', 'There are three.'], ['Four', 'The a is a vowel.']], 'spl: three consonants together.'],
            ['Which is a common mistake when saying “school”?', 'Adding a vowel: “s-ku-ool”', [['Saying the s', 'The s must be said.'], ['Saying the k sound', 'The k sound is correct.'], ['Saying it quickly', 'Speed is not the error.']], 'Do not break the cluster with an extra vowel.'],
            ['Which word ENDS with a consonant cluster?', 'desk', [['day', 'Ends with a vowel sound.'], ['see', 'Ends with a vowel sound.'], ['go', 'Ends with a vowel sound.']], 'sk at the end: a final cluster.'],
            ['In “asked”, what final cluster should you say?', 'skt (/skt/)', [['sk only', 'The past ending t is dropped.'], ['k only', 'The s is dropped.'], ['sked with an extra vowel', 'Adds a syllable that is not there.']], 'Asked ends /skt/; keep every consonant.'],
            ['Which pair shows that dropping a consonant changes the word?', 'test / tess', [['cat / cats', 'Adding s is a different change.'], ['big / bigger', 'A suffix, not dropping.'], ['run / ran', 'A vowel change.']], 'Dropping t from st changes test to tess.'],
            ['Which word has a THREE-consonant cluster at the start?', 'spring', [['sport', 'sp: two.'], ['bring', 'br: two.'], ['ring', 'r: one.']], 'spr: three consonants.'],
        ], '{q}', 'Say every consonant in the cluster; do not add vowels between them or drop the last one.', 'concept', 35),
        eng_choose([
            ['Which is the correct pronunciation of “months”?', 'mʌnθs (keep θ and s)', [['mons', 'Drops the th.'], ['montis', 'Adds a vowel.'], ['moths', 'Changes the vowel and drops n.']], 'Months ends with the cluster nθs.'],
            ['Which word contains the cluster “nd” at the end?', 'hand', [['hat', 'Ends in t.'], ['hen', 'Ends in n only.'], ['head', 'Ends in d only.']], 'hand ends /nd/.'],
            ['Saying “street” as “sitreet” is an example of what?', 'Adding a vowel inside a cluster', [['Dropping a consonant', 'Nothing is dropped.'], ['Correct pronunciation', 'It is not correct.'], ['Changing stress only', 'A sound is added.']], 'Keep str together: no vowel between.'],
            ['How many consonant sounds end the word “texts”?', 'Four: k, s, t, s', [['Two', 'Count each sound.'], ['One', 'There are four.'], ['Three', 'Count again: k-s-t-s.']], 'texts /teksts/ ends with four consonant sounds.'],
            ['Which word does NOT begin with a cluster?', 'phone', [['play', 'pl.'], ['tree', 'tr.'], ['glass', 'gl.']], 'ph is one sound, /f/.'],
            ['Why practise clusters slowly first?', 'To make sure every consonant is heard before speeding up', [['To add extra vowels', 'Vowels should not be added.'], ['Because clusters are rare', 'They are common.'], ['To drop hard sounds', 'All sounds should be kept.']], 'Slow first, then natural speed.'],
            ['Which word ends with the cluster “lp”?', 'help', [['hello', 'Ends in a vowel.'], ['hell', 'Ends in l.'], ['heap', 'Ends in p only.']], 'help ends /lp/.'],
        ], '', 'A cluster is two or more consonant sounds together: keep them together, keep them all.', 'concept', 35),
    ],
    'EN-077' => [
        eng_choose([
            ['Which is a semi-formal letter?', 'A letter to your friend’s father thanking him for a gift', [['A letter to your best friend', 'Informal.'], ['A letter applying for a job', 'Formal.'], ['A complaint to the council', 'Formal.']], 'Semi-formal: to someone you know but respect.'],
            ['Which salutation suits a semi-formal letter to your teacher?', 'Dear Mr Bello,', [['Dear Sir/Madam,', 'Formal and impersonal.'], ['Hi Bello!', 'Too casual.'], ['My dearest Bello,', 'Too intimate.']], 'Title plus surname.'],
            ['Which closing suits a semi-formal letter?', 'Yours sincerely,', [['Yours faithfully,', 'For unknown, formal readers.'], ['Your buddy,', 'Too casual.'], ['XOXO', 'Far too casual.']], 'Yours sincerely, then your name.'],
            ['How many addresses does a semi-formal letter usually have?', 'One: the writer’s', [['Two, like a formal letter', 'The receiver’s address is usually left out.'], ['None', 'The writer’s address is given.'], ['Three', 'No.']], 'Like the informal letter, one address and the date.'],
            ['Which sentence fits the TONE of a semi-formal letter to your aunt’s employer?', 'I am grateful for the kindness you showed my aunt.', [['Thanks a mil, boss!', 'Too casual.'], ['I hereby notify you of my gratitude.', 'Stiff and overly formal.'], ['Your thing for my aunt was cool.', 'Slang.']], 'Polite, warm, correct.'],
            ['Which detail belongs in a semi-formal letter to a neighbour about noise?', 'A polite explanation and a request', [['A threat to report him', 'Too hostile.'], ['A joke about his music', 'Undermines the request.'], ['Your school results', 'Irrelevant.']], 'Respectful and to the point.'],
            ['Does a semi-formal letter need a heading?', 'Not usually', [['Always, in capitals', 'Headings are a formal-letter feature.'], ['Only when it is long', 'Length does not decide.'], ['Two headings', 'No.']], 'Usually no heading.'],
        ], '{q}', 'Semi-formal: someone you know but respect. Polite and warm; title and name; Yours sincerely.', 'concept', 35),
        eng_choose([
            ['Which opening suits a semi-formal letter to your pastor?', 'I hope this letter finds you well.', [['What’s up?', 'Too casual.'], ['I am writing to lodge a complaint.', 'Too formal unless complaining.'], ['Yo!', 'Slang.']], 'A respectful, friendly opening.'],
            ['Which letter is semi-formal rather than informal?', 'To your friend’s mother, asking to stay for a weekend', [['To your brother about football', 'Informal.'], ['To your cousin about a party', 'Informal.'], ['To your classmate about homework', 'Informal.']], 'An older person you know: semi-formal.'],
            ['In a semi-formal letter, how should you sign off?', 'Yours sincerely, followed by your full name', [['Love, followed by your nickname', 'Too intimate.'], ['Yours faithfully, followed by an initial', 'Wrong closing for a named person.'], ['Only your nickname', 'Too casual.']], 'Sincerely and full name.'],
            ['Which word suits a semi-formal letter?', 'appreciate', [['dope', 'Slang.'], ['heretofore', 'Too stiff and legal.'], ['lol', 'Text-speak.']], 'Standard, polite vocabulary.'],
            ['What is the right tone for a semi-formal letter of apology to a teacher?', 'Respectful and sincere', [['Defensive', 'Undermines the apology.'], ['Jokey', 'Not sincere.'], ['Cold and official', 'Lacks warmth.']], 'Respect plus sincerity.'],
            ['Where does the date go in a semi-formal letter?', 'Under the writer’s address', [['Before the salutation, on the left', 'Not usual.'], ['At the end', 'It goes at the top.'], ['It is optional', 'Letters are dated.']], 'Address then date.'],
            ['Which is a semi-formal letter purpose?', 'Asking a family friend for advice about a course', [['Applying to a university', 'Formal.'], ['Chatting with your sister', 'Informal.'], ['Writing to a newspaper editor', 'Formal.']], 'A known but respected reader.'],
        ], '', 'Between informal and formal: respectful, warm and correct.', 'concept', 35),
    ],
    'EN-078' => [
        eng_choose([
            ['What is the main aim of a narrative essay?', 'To tell a story', [['To argue a point', 'That is argumentative.'], ['To explain how something works', 'That is expository.'], ['To list facts', 'Not a story.']], 'Narratives tell what happened.'],
            ['What is the main aim of a descriptive essay?', 'To paint a picture of a person, place or thing', [['To tell events in order', 'That is narrative.'], ['To persuade', 'That is argumentative.'], ['To give instructions', 'That is a procedure.']], 'Description makes the reader see, hear and feel.'],
            ['Which sentence is most DESCRIPTIVE?', 'The old market smelled of smoked fish and ripe mangoes.', [['I went to the market.', 'Plain narration.'], ['Markets are important.', 'A claim.'], ['The market opens at six.', 'A fact.']], 'Sensory details describe.'],
            ['Which opening best hooks the reader of a narrative?', 'The scream came from the empty classroom.', [['This essay is about a day.', 'Flat.'], ['Once upon a time there was a day.', 'Vague.'], ['I will now tell a story.', 'Flat announcement.']], 'Start with action or mystery.'],
            ['Narratives are usually told in which order?', 'The order in which events happened', [['Alphabetical order', 'No.'], ['Order of importance only', 'That suits arguments.'], ['Random order', 'Confusing.']], 'Chronological order, unless a flashback is used on purpose.'],
            ['Which detail uses the sense of HEARING?', 'The drums thundered across the square.', [['The sky was orange.', 'Sight.'], ['The pepper burned my tongue.', 'Taste.'], ['The cloth felt rough.', 'Touch.']], 'Thundered is a sound.'],
            ['Which is the best title for a descriptive essay?', 'My Grandmother’s Kitchen', [['Why We Should Plant Trees', 'Argumentative.'], ['How to Make Garri', 'Expository.'], ['The Day I Got Lost', 'Narrative.']], 'A person, place or thing to describe.'],
        ], '{q}', 'Narrative tells events; descriptive paints a picture with the senses.', 'concept', 35),
        eng_choose([
            ['Which sentence SHOWS rather than tells?', 'Her hands shook as she opened the letter.', [['She was nervous.', 'Tells the feeling.'], ['She felt something.', 'Vague.'], ['She was a person.', 'Empty.']], 'Show feelings through actions and details.'],
            ['What does a narrative essay need for a satisfying end?', 'A resolution: how things turned out', [['A list of facts', 'Not an ending.'], ['A new character', 'Starts a new story.'], ['Yours faithfully', 'A letter ending.']], 'Resolve the story’s problem.'],
            ['Which is a FIRST-PERSON narrative sentence?', 'I ran to the gate as the bell rang.', [['He ran to the gate.', 'Third person.'], ['They ran to the gate.', 'Third person.'], ['Run to the gate.', 'A command.']], 'First person uses I or we.'],
            ['Which word makes this description sharper? “The ___ road wound up the hill.”', 'dusty', [['nice', 'Vague.'], ['good', 'Vague.'], ['thing', 'Not an adjective.']], 'Precise, sensory adjectives describe.'],
            ['In a descriptive essay, how should details be ordered?', 'In a clear pattern, such as near to far or top to bottom', [['Randomly', 'Confusing.'], ['By word length', 'Not meaningful.'], ['Alphabetically', 'Not meaningful.']], 'A spatial pattern guides the reader.'],
            ['Which is a narrative essay title?', 'The Day Our Bus Broke Down', [['My Village', 'Descriptive.'], ['Should Uniforms Be Abolished?', 'Argumentative.'], ['How Rain Forms', 'Expository.']], 'It promises a story.'],
            ['Which helps a narrative most?', 'A problem or conflict the main character must face', [['A list of names', 'No story.'], ['A table of facts', 'Not narrative.'], ['No events at all', 'Nothing to tell.']], 'Conflict drives a story.'],
        ], '', 'Show with detail; order events or details clearly; end with a resolution or a lasting picture.', 'concept', 35),
    ],
    'EN-079' => [
        eng_choose([
            ['What is the main aim of an expository essay?', 'To explain or inform', [['To tell a story', 'Narrative.'], ['To describe a place', 'Descriptive.'], ['To win an argument', 'Argumentative.']], 'Exposition explains clearly and factually.'],
            ['What is the main aim of an argumentative essay?', 'To persuade the reader to accept a position', [['To describe a market', 'Descriptive.'], ['To tell what happened', 'Narrative.'], ['To list instructions', 'Expository/procedural.']], 'Argument takes a side and supports it.'],
            ['Which title suits an EXPOSITORY essay?', 'How Vaccines Protect the Body', [['Vaccines Must Be Compulsory', 'Argumentative.'], ['The Day I Got My Vaccine', 'Narrative.'], ['The Busy Clinic', 'Descriptive.']], 'How or why something works: expository.'],
            ['Which title suits an ARGUMENTATIVE essay?', 'Homework Should Be Banned', [['How Homework Is Set', 'Expository.'], ['My Homework Desk', 'Descriptive.'], ['The Night I Forgot My Homework', 'Narrative.']], 'A debatable claim: argumentative.'],
            ['Which tone suits an expository essay?', 'Clear, neutral and factual', [['Emotional and pleading', 'Not neutral.'], ['Sarcastic', 'Not neutral.'], ['Full of slang', 'Not formal.']], 'Explain without taking sides.'],
            ['Which sentence belongs in an argumentative essay but NOT an expository one?', 'Therefore, the government must act now.', [['Rain forms when vapour cools.', 'Explanatory.'], ['The process has three stages.', 'Explanatory.'], ['First, mix the flour.', 'Instructional.']], 'A call to act shows a position.'],
            ['An expository essay on the water cycle is best organised…', 'in the order of the stages', [['by the writer’s opinions', 'Not expository.'], ['randomly', 'Confusing.'], ['as a story with characters', 'Not expository.']], 'Follow the process step by step.'],
